import{_ as t,c as o,o as a,ag as r}from"./chunks/framework.DuVOYUUM.js";const p=JSON.parse('{"title":"Environment Setup","description":"","frontmatter":{},"headers":[],"relativePath":"projects/igvc-2026/software/environment-setup/index.md","filePath":"projects/igvc-2026/software/environment-setup/index.md","lastUpdated":1790647345000}'),s={name:"projects/igvc-2026/software/environment-setup/index.md"};function n(i,e,d,l,h,c){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="environment-setup" tabindex="-1">Environment Setup <a class="header-anchor" href="#environment-setup" aria-label="Permalink to &quot;Environment Setup&quot;">​</a></h1><h2 id="ros-2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros-2" aria-label="Permalink to &quot;ROS 2&quot;">​</a></h2><p>ROS 2 is an open-source communications middleware that allows various sensors, applications, drivers, etc., to communicate with each other in an organized manner. This is the main tool/library which we will use to create the software package for our robot.</p><p>Read the official documentation <a href="https://docs.ros.org/en/jazzy/" target="_blank" rel="noreferrer">here</a>.</p><h3 id="installation-methods" tabindex="-1">Installation methods <a class="header-anchor" href="#installation-methods" aria-label="Permalink to &quot;Installation methods&quot;">​</a></h3><p>ROS 2 is supported on multiple platforms, but we recommend either using a native installation of Ubuntu or a containerized Docker environment, as these approaches are the most stable and easiest to support as a team. You can reference the official documentation (linked above) for alternative installation options.</p><p>Our recommended setup paths:</p><ul><li><a href="./native">Native</a></li><li><a href="./docker">Docker</a></li></ul><h3 id="which-method-should-you-choose" tabindex="-1">Which method should you choose? <a class="header-anchor" href="#which-method-should-you-choose" aria-label="Permalink to &quot;Which method should you choose?&quot;">​</a></h3><p>The installation method you choose mostly depends on what tasks or goals you are trying to accomplish. That being said, both are equally viable options, however most of the leadership is familiar with the native installation. This table discusses some of the benefits &amp; drawbacks of each method:</p><table tabindex="0"><thead><tr><th>Topic</th><th>Docker</th><th>Native</th></tr></thead><tbody><tr><td><strong>Setup Difficulty</strong></td><td>Often simpler. All dependencies, tools, etc., are bundled.</td><td>Done manually. Everything needs to be installed yourself.</td></tr><tr><td><strong>Operating System</strong></td><td>Can be run anywhere (Windows, MacOS, another Linux distro)</td><td>Ubuntu only</td></tr><tr><td><strong>Performance</strong></td><td>Near-native speed</td><td>Fastest possible</td></tr><tr><td><strong>Hardware Access</strong></td><td>Extra setup needed for USB devices, GPUs, networking, etc</td><td>Easiest device access</td></tr><tr><td><strong>GUI Tools</strong></td><td>Extra setup needed (Display forwarding)</td><td>Works out-of-the-box</td></tr><tr><td><strong>Rollback safety</strong></td><td>Can reset back to default state at any time</td><td>Can be <em>technically</em> be done, but more effort</td></tr><tr><td><strong>Debugging</strong></td><td>Extra layer to access tools, files, logs</td><td>Direct access to access tools, files, logs</td></tr></tbody></table><p>See (or message) Kayla Dawkins (@danielle217) if you have any questions about the benefits of Docker or issues with the setup</p><h2 id="setting-up-your-workspace" tabindex="-1">Setting up your workspace <a class="header-anchor" href="#setting-up-your-workspace" aria-label="Permalink to &quot;Setting up your workspace&quot;">​</a></h2><p>A workspace in ROS 2 refers to the directory which contains the ROS 2 packages used in your project. All of the code that we write will be contained inside of a package in the workspace.</p><p>Our recommended workspace setup:</p><ul><li><a href="./first-run">Running the project for the first time</a></li></ul>',16)]))}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
